// Live Run auto-refresh.
// ToolJet has no per-query interval and the Timer component exposes no reset
// action, so this self-scheduling loop is the polling mechanism.
// It re-runs ONE query: getLiveRun already fans out to getRunProgress,
// getLiveSpecs and getLiveTests via its onDataQuerySuccess events.
//
// This loop owns exactly ONE variable:
//   variables.clrTick - heartbeat timestamp; components read it so that
//                       time-derived UI ("Started 3m ago", elapsed) re-renders
//                       even when the query rows are byte-identical.
//
// It deliberately does NOT publish liveRun / clrStatus any more. Every query
// now writes its own rows into a variable from its onDataQuerySuccess handler
// (liveRun, clrStatus, runProgress, liveSpecs, liveTests, runs, projects), and
// the components read only those. Writing liveRun here as well would publish a
// one-tick-stale row on every tick and fight the success handler.

// One loop per tab - clear any previous one so page navigation cannot stack timers.
if (window.__clrPoll) { clearTimeout(window.__clrPoll); window.__clrPoll = null; }

var FAST = 5000;   // a run is in flight
var IDLE = 20000;  // nothing running, or we are on another page

function clrTick() {
  var delay = IDLE;
  try {
    // Only Live Run consumes this data; skip the work on the other pages.
    var onOtherPage = /\/(runs-history|flaky-tests|projects)(\/|$|\?)/.test(window.location.pathname);
    if (!onOtherPage) {
      // getData() reads live resolved state (queries.* itself is a snapshot clone)
      var rows = queries.getLiveRun.getData() || [];
      var row = rows[0] || null;
      if (row && row.status === 'running') { delay = FAST; }

      actions.setVariable('clrTick', Date.now());

      queries.getLiveRun.run();
    }
  } catch (e) {
    // never let the poller die
  }
  window.__clrPoll = setTimeout(clrTick, delay);
}

window.__clrPoll = setTimeout(clrTick, FAST);
return 'live polling started (5s while running, 20s idle)';
